import unicodedata


def slugify(s):
    s = s.lower()
    # Remove diacritics
    s = unicodedata.normalize('NFD', s)
    s = ''.join(ch for ch in s if unicodedata.category(ch) != 'Mn')
    # Replace non-alphanumeric with hyphen
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            out.append('-')
    # Collapse consecutive hyphens and strip leading/trailing
    result = ''
    for ch in out:
        if ch == '-' and result.endswith('-'):
            continue
        result += ch
    return result.strip('-')

